1	// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
2	// against a member. Everything it decides was decided elsewhere: the flows judge and
3	// write, `terminalFor` says what happens to the PR, `deliveryFor` says whether the PR
4	// this run opens is the member's to land. What lives here is the I/O none of them may
5	// carry — the clone, the branch, the commit, the push, the PR, and the hand-off.
6	//
7	// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
8	// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
9	// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
10	// and let the shared landing helper own every nuance of arming versus merging. A
11	// second, cleverer shape here would be a second set of the same bugs.
12	//
13	// IT NO LONGER ASKS WHICH MECHANISM SERVES THE REPO. There is one, and its only
14	// rival was deleted in #768 Phase 5, so the question had exactly one answer for
15	// every member that could ask it; the `maintenance` block that held it is gone
16	// (#1252) and `engine/served-by.mjs` is deprecated with it.
17	import { execFileSync } from 'node:child_process';
18	import { readFileSync, existsSync, mkdtempSync } from 'node:fs';
19	import { join } from 'node:path';
20	import { tmpdir } from 'node:os';
21	import { pathToFileURL } from 'node:url';
22	import { removeTree } from '../../../../engine/remove-tree.mjs';
23	import {
24	  deliveryFor, pullCreateError, landDelivery,
25	} from '../../../claudinite-tasks/public/delivery.mjs';
26	import { withTaskTrailer } from '../../../claudinite-tasks/public/work-item-grammar.mjs';
27	import { settingsPath, SETTINGS_FILE } from '../../../../engine/settings-file.mjs';
28	
29	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
30	// What this worker stamps on everything it commits and merges (task-trailer.mjs).
31	const UPDATE_TASK_ID = 'claudinite-lifecycle/update';
32	const API = 'https://api.github.com';
33	
34	const git = (args, opts = {}) =>
35	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
36	
37	async function gh(token, path, { method = 'GET', body } = {}) {
38	  const res = await fetch(`${API}${path}`, {
39	    method,
40	    headers: {
41	      authorization: `Bearer ${token}`,
42	      accept: 'application/vnd.github+json',
43	      'x-github-api-version': '2022-11-28',
44	      ...(body ? { 'content-type': 'application/json' } : {}),
45	    },
46	    body: body ? JSON.stringify(body) : undefined,
47	  });
48	  let json = null;
49	  try { json = await res.json(); } catch { /* empty body */ }
50	  return { status: res.status, json };
51	}
52	
53	// --- pure helpers (exported, unit-tested git-free) --------------------------
54	
55	// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
56	// and exits 0 is worse than no gate at all — it reports a qualification that never
57	// happened — and that is not hypothetical: this exact gate went vacuous the day the
58	// canary flipped to `updates`, because the workflow drove the canary's baselining
59	// worker, which correctly stood down and exited 0 in zero seconds for weeks.
60	//
61	// So the rehearsal announces that it really ran, and the workflow fails when this
62	// line is absent. Any future path that skips the update is caught by construction
63	// rather than by someone noticing a suspiciously fast green.
64	export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';
65	
66	// Does this run UPDATE the pull request the executor named, or open one? The
67	// executor resolves `amend_existing_or_create_new_pr` before this subprocess
68	// starts and hands the number in; all this decides is whether the answer still
69	// holds by the time the branch is pushed.
70	//
71	// A named pull request that is no longer open was closed under the run. The branch
72	// is still the one to push to — it is the target the executor chose — but the
73	// delivery has to be a NEW pull request: a push onto a closed one changes nothing
74	// anybody sees, and the run would report a delivery it did not make.
75	export const amendsPull = (targetPr, pull) =>
76	  Boolean(targetPr) && pull?.state === 'open' && pull?.number === Number(targetPr);
77	
78	// The PR title and body for a terminal. The body is what a human reads when the run
79	// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
80	// says "an update ran" makes every reader re-derive the thing the run already knew.
81	//
82	// THE TITLE IS A SUMMARY, THE BODY IS THE DETAIL. A title that names every moved pack
83	// grows with the number a member declares, and a PR list is where that is least
84	// readable — so the packs collapse to a count and only the engine keeps its versions.
85	export function updatePullText(terminal, { engine, packs }) {
86	  const engineMoved = engine?.from !== engine?.to;
87	  const movedPacks = (packs?.plan ?? []).filter((p) => p.from !== p.to);
88	  const moved = [
89	    ...(engineMoved ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
90	    ...movedPacks.map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
91	  ];
92	  const summary = [
93	    ...(engineMoved ? [`engine ${engine?.from == null ? 'unstamped' : `v${engine.from}`} → v${engine?.to}`] : []),
94	    ...(movedPacks.length ? [`${movedPacks.length} pack${movedPacks.length === 1 ? '' : 's'} upgraded`] : []),
95	  ];
96	  const title = summary.length ? `Claudinite update: ${summary.join(' and ')}` : 'Claudinite update';
97	  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
98	  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
99	  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
100	  if (terminal.action === 'needs-human') {
101	    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
102	  } else if (terminal.action === 'apply-stage') {
103	    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content and runs its tests over what this converge wrote, before anything merges.');
104	  }
105	  return { title, body: `${lines.join('\n')}\n` };
106	}
107	
108	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
109	
110	export async function worker({ root, repo, defaultBranch, token, target }) {
111	  const base = defaultBranch ?? 'main';
112	  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
113	  // report, and restore the working tree — no branch, no commit, no PR, and above
114	  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
115	  // which is exactly what the next update's anti-rewind guard refuses: a rehearsal
116	  // that wedges its own canary.
117	  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
118	
119	  // Either settings-file name, in the rename's read order: this worker is VENDORED,
120	  // so the copy running on a member may predate the record that renamed its own
121	  // file — and one that only knew the new name would report "nothing to update" on
122	  // every repo still carrying the old one.
123	  const settingsFile = settingsPath(root);
124	  if (!existsSync(settingsFile)) { console.log(`update: no ${SETTINGS_FILE} — nothing to update`); return; }
125	  const declaration = JSON.parse(readFileSync(settingsFile, 'utf8'));
126	
127	  // One override, one direction: a repo that asked for review gets its PR opened and
128	  // left; every other repo — the normal shape, the key absent — has it landed.
129	  const delivery = deliveryFor(declaration);
130	
131	  // THE TARGET, AND IT IS REQUIRED. Which branch this run pushes to, and which pull
132	  // request it delivers on, is the executor's decision: the task declares
133	  // `supersede_existing_pr`, the executor resolved it before this subprocess started
134	  // — this cycle's own fresh branch, with the last cycle's pull request closed once
135	  // this one's exists (or landed first, where it had concluded green) — and handed
136	  // it in. Nothing here reads the open pull requests or picks a name.
137	  //
138	  // That disposal is what keeps a member that cannot land from accumulating a line
139	  // of obsolete pull requests, one a night: the update is a full recompute from
140	  // the base, so the one left standing is always this cycle's answer.
141	  //
142	  // Required, because an outcome that opens a pull request always resolves a branch:
143	  // an absent one is an executor that predates the hand-off, whose mount is too far
144	  // behind to converge itself, and delivering on a branch nothing is watching is
145	  // worse than saying so. The disposal and the minted branch this worker fell back
146	  // on are gone with the window they were held for (#1698). A REHEARSAL is exempt —
147	  // it restores the tree and delivers nothing, and the canary gate drives this worker
148	  // with no executor at all.
149	  const branch = target.branch;
150	  const targetPr = target.pr;
151	  if (!rehearsalRef && !branch) {
152	    console.error('claudinite-needs-human: action — this mount is too far behind to converge itself;'
153	      + ' re-vendor it from the canon');
154	    throw new Error('no CLAUDINITE_TARGET_BRANCH — this repo\'s executor predates the target hand-off (#1695)');
155	  }
156	
157	  // The flows run from a FRESH CANON CLONE, never from this repo's mount: the mount is
158	  // the thing being replaced, and a flow executing its own stale copy is how a broken
159	  // update makes itself permanent.
160	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
161	  try {
162	    // A rehearsal names the ref it is qualifying; an ordinary cycle takes the
163	    // default branch, which is the only thing a member should ever converge onto.
164	    git(rehearsalRef
165	      ? ['clone', '--depth', '1', '--branch', rehearsalRef, CANON_URL, tmp]
166	      : ['clone', '--depth', '1', CANON_URL, tmp]);
167	    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
168	    const { engineUpdate } = await load('packs/claudinite-lifecycle/updates/engine-update.mjs');
169	    const { packUpdate } = await load('packs/claudinite-lifecycle/updates/pack-update.mjs');
170	    const { terminalFor } = await load('packs/claudinite-lifecycle/updates/terminals.mjs');
171	
172	    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
173	    // pack flow enforces that against what this repo HAS. Running packs first would
174	    // check every pack against yesterday's engine and block updates that the very
175	    // next step would have made legal.
176	    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
177	    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
178	    let packs = null;
179	    if (engine.status !== 'needs-human') {
180	      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
181	      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
182	    }
183	
184	    // The engine's terminal wins when it stopped the run: nothing downstream of a
185	    // refused engine update is trustworthy, including a pack flow that never ran.
186	    const outcome = engine.status === 'needs-human' ? engine : packs;
187	    const terminal = terminalFor(outcome);
188	
189	    // A REHEARSAL STOPS HERE. It has the only answer it was asked for — does this
190	    // canon ref converge this member and leave it green — so it says so and puts the
191	    // tree back exactly as it found it. Restoring is not tidiness: an uncommitted
192	    // converge left behind would be picked up by the canary's own next cycle as if a
193	    // human had written it.
194	    if (rehearsalRef) {
195	      git(['-C', root, 'checkout', '--', '.']);
196	      git(['-C', root, 'clean', '-fd']);
197	      if (terminal.action === 'needs-human') {
198	        console.error(`update: rehearsing ${rehearsalRef} FAILED — ${terminal.why}`);
199	        process.exitCode = 1;
200	        return;
201	      }
202	      console.log(`${REHEARSAL_MARKER} ${repo} against ${rehearsalRef} — ${terminal.action}: ${terminal.why}`);
203	      return;
204	    }
205	
206	    // AN APPLY STAGE IS NOT "NOTHING CHANGED" (#1545). A run that withheld a workflow
207	    // file leaves the pack unstamped, precisely so the record stays in range — so on a
208	    // cycle that re-stages content the branch already carries, the tree can be clean
209	    // while a delivery is still owed. Returning here would skip the PR, and the
210	    // apply-stage request is written below it, so nobody would ever be asked to deliver:
211	    // the silent loss this whole fix exists to end, one step further along. The empty
212	    // commit is the point — the apply stage's own move is what fills the PR.
213	    const changed = git(['-C', root, 'status', '--porcelain']).trim();
214	    if (!changed && terminal.action !== 'needs-human' && terminal.action !== 'apply-stage') {
215	      console.log('update: nothing changed — no branch, no PR');
216	      return;
217	    }
218	
219	    git(['-C', root, 'checkout', '-B', branch]);
220	    git(['-C', root, 'add', '-A']);
221	    const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
222	    const { title, body } = updatePullText(terminal, { engine, packs });
223	    git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
224	      // The trailer is what classifies this converge as machinery to every
225	      // movement-gated task: the mount refreshing is not the project moving.
226	      'commit', ...(staged.length ? [] : ['--allow-empty']), '-m', withTaskTrailer(title, UPDATE_TASK_ID)]);
227	    // A REWRITE THAT CHANGES NOTHING IS NOT A REWRITE, and force-pushing one is not
228	    // free: it gives the pull request a new head, which discards every check that had
229	    // already run on it. This worker delivers on whatever branch the executor handed
230	    // it and never on one of its own, so a branch it is handed twice — the target
231	    // protocol's to decide, not this file's — must not have its checks reset by a
232	    // cycle that recomputed the same tree from the same base. Compared as TREES
233	    // rather than commits: this cycle's commit is new by construction (its own
234	    // timestamp), and it is the content that decides whether anything is owed.
235	    const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
236	    let standing = null;
237	    try {
238	      git(['-C', root, 'fetch', '--depth', '1', remote, `refs/heads/${branch}`]);
239	      standing = { sha: git(['-C', root, 'rev-parse', 'FETCH_HEAD']).trim(), tree: git(['-C', root, 'rev-parse', 'FETCH_HEAD^{tree}']).trim() };
240	    } catch { /* no such branch on the remote yet — this run opens it */ }
241	    const pushed = standing?.tree !== git(['-C', root, 'rev-parse', 'HEAD^{tree}']).trim();
242	    if (pushed) git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
243	    else console.log(`update: ${branch} already carries this converge — left standing, so its checks are not reset`);
244	
245	    // The head the branch now carries, which the landing lane polls the checks of. A
246	    // pull request READ back carries the previous cycle's sha, and polling that one
247	    // waits on runs that will never come — while on the cycle that pushed nothing,
248	    // the sha with the checks on it is the one already standing.
249	    const head = pushed ? git(['-C', root, 'rev-parse', 'HEAD']).trim() : standing.sha;
250	
251	    const named = targetPr ? await gh(token, `/repos/${repo}/pulls/${targetPr}`) : null;
252	    let pr;
253	    if (amendsPull(targetPr, named?.json)) {
254	      // Rewritten, title and body included: both say which terminal fired and what
255	      // moved, and this cycle's answer to that is not the last one's.
256	      const patched = await gh(token, `/repos/${repo}/pulls/${targetPr}`, { method: 'PATCH', body: { title, body } });
257	      if (patched.status !== 200) throw new Error(`could not update PR #${targetPr}: ${patched.json?.message ?? `HTTP ${patched.status}`}`);
258	      pr = patched.json;
259	      console.log(`update: rewrote PR #${pr.number} on ${branch} (${terminal.action})`);
260	    } else {
261	      const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
262	      const failure = pullCreateError(created.status, created.json);
263	      if (failure) throw new Error(`could not open the update PR for ${branch}: ${failure}`);
264	      pr = created.json;
265	      console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);
266	    }
267	    pr = { ...pr, head: { ...pr.head, ref: branch, sha: head } };
268	
269	    // The terminal, acted on. Only one action merges, and it is the one the flow
270	    // already judged green — everything else leaves the PR standing, labelled or
271	    // handed to the agent stage.
272	    if (terminal.action === 'merge') {
273	      await landDelivery({ token, repo, base, pr, delivery, task: UPDATE_TASK_ID });
274	    } else if (terminal.action === 'needs-human') {
275	      await gh(token, `/repos/${repo}/issues/${pr.number}/labels`, { method: 'POST', body: { labels: [terminal.label] } });
276	      console.error(`update: left PR #${pr.number} open and labelled ${terminal.label} — ${terminal.why}`);
277	      // NON-ZERO, so the work item lands in `needs-human` rather than closing
278	      // `task:done`. This terminal means the update DID NOT DELIVER — the PR
279	      // is parked awaiting a person — and a run that delivered nothing must not
280	      // report success. Exiting 0 here is what hid #939 for five days: every
281	      // member's nightly update closed `task:done` while its PR sat parked, so
282	      // the whole fleet was frozen and every signal said healthy. This is the
283	      // "reserve non-zero for genuine breakage" rule's genuine breakage: the
284	      // member is not converging and nothing else will say so.
285	      process.exitCode = 1;
286	    } else if (terminal.action === 'apply-stage') {
287	      console.log(`update: requested the apply stage — ${terminal.why}`);
288	      return {
